import React from 'react';
import './DetailsStep.css';

const DetailsStep = ({ 
    character, 
    handleWeaponChange, 
    handleRemoveWeapon, 
    handleAddWeapon, 
    handleSpellChange,    
    handleRemoveSpell,    
    handleAddSpell,       
    handleSlotChange,
    calculateModifier, 
    profBonus 
}) => {

    // YENİ: Zar ekleme motoru. Aynı zara basılırsa sayısını artırır (örn: 1d8 -> 2d8)
    const handleAddDice = (weaponId, currentStr, die) => {
        let str = (currentStr || '').trim();
        const regex = new RegExp(`(\\d+)${die}\\b`);
        const match = str.match(regex);

        if (match) {
            const count = parseInt(match[1]) + 1;
            str = str.replace(regex, `${count}${die}`);
        } else {
            str = str ? `${str} + 1${die}` : `1${die}`;
        }
        handleWeaponChange(weaponId, 'damageDice', str);
    };

    return (
        <div className="step-content fade-in">
            {/* --- WEAPONS SECTION --- */}
            <div className="weapons-section">
                <div className="section-header">
                    <h2>Attacks & Weapons</h2>
                    <button type="button" className="add-weapon-btn" onClick={handleAddWeapon}>+ NEW WEAPON</button>
                </div>

                <div className="weapons-list">
                    {character.weapons.map((weapon) => {
                        const statMod = calculateModifier(character.stats[weapon.stat || 'Strength']);
                        const totalAtk = statMod + (weapon.isProficient ? profBonus : 0) + (parseInt(weapon.atkBonus) || 0);

                        return (
                            <div className="weapon-card" key={weapon.id}>
                                <div className="weapon-main-row">
                                    <select className="weapon-type-select" value={weapon.type} onChange={(e) => handleWeaponChange(weapon.id, 'type', e.target.value)}>
                                        <option value="Melee">⚔️ Melee</option>
                                        <option value="Ranged">🏹 Ranged</option>
                                    </select>
                                    <input 
                                        type="text" 
                                        className="weapon-name" 
                                        placeholder="Weapon Name..." 
                                        value={weapon.name} 
                                        onChange={(e) => handleWeaponChange(weapon.id, 'name', e.target.value)} 
                                    />
                                    <button type="button" className="remove-weapon-btn" onClick={() => handleRemoveWeapon(weapon.id)}>✕</button>
                                </div>

                                <div className="weapon-stats-row">
                                    <div className="weapon-input-group">
                                        <label>Ability</label>
                                        <select value={weapon.stat} onChange={(e) => handleWeaponChange(weapon.id, 'stat', e.target.value)}>
                                            <option value="Strength">STR</option>
                                            <option value="Dexterity">DEX</option>
                                            <option value="Constitution">CON</option>
                                            <option value="Intelligence">INT</option>
                                            <option value="Wisdom">WIS</option>
                                            <option value="Charisma">CHA</option>
                                        </select>
                                    </div>
                                    <div className="weapon-input-group">
                                        <label>Atk Bonus</label>
                                        <input type="number" placeholder="+0" value={weapon.atkBonus} onChange={(e) => handleWeaponChange(weapon.id, 'atkBonus', e.target.value)} />
                                    </div>

                                    {/* YENİ: Gelişmiş Damage Dice Alanı */}
                                    <div className="weapon-input-group damage-dice-group">
                                        <label>Damage Dice</label>
                                        <div className="dice-input-wrapper">
                                            <input type="text" placeholder="e.g. 1d8" value={weapon.damageDice} onChange={(e) => handleWeaponChange(weapon.id, 'damageDice', e.target.value)} />
                                            <button type="button" className="clear-dice-btn" onClick={() => handleWeaponChange(weapon.id, 'damageDice', '')} title="Clear Dice">✕</button>
                                        </div>
                                        <div className="dice-buttons">
                                            {['d4', 'd6', 'd8', 'd10', 'd12', 'd20'].map(die => (
                                                <button key={die} type="button" className="dice-btn" onClick={() => handleAddDice(weapon.id, weapon.damageDice, die)}>
                                                    {die}
                                                </button>
                                            ))}
                                        </div>
                                    </div>

                                    <div className="weapon-input-group prof-toggle-group">
                                        <label>Prof.</label>
                                        <div className={`custom-prof-toggle ${weapon.isProficient ? 'active' : ''}`} onClick={() => handleWeaponChange(weapon.id, 'isProficient', !weapon.isProficient)}></div>
                                    </div>
                                </div>

                                <div className="weapon-description-row">
                                    <textarea 
                                        placeholder="Properties (Finesse, Light), Range, or Special Effects..." 
                                        value={weapon.description} 
                                        onChange={(e) => handleWeaponChange(weapon.id, 'description', e.target.value)}
                                    />
                                </div>

                                <div className="weapon-summary-bar">
                                    <div className="summary-item">HIT: <span>+{totalAtk}</span></div>
                                    <div className="summary-item">DMG: <span>{weapon.damageDice || '--'} {statMod >= 0 ? `+${statMod}` : statMod}</span></div>
                                    {weapon.type === 'Ranged' && <div className="summary-item range-tag">Ranged</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* --- SPELL SLOTS BAR --- */}
            {character.spellSlots && (
                <div className="spell-slots-bar">
                    <h3>Spell Slots</h3>
                    <div className="slots-grid">
                        {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(lvl => (
                            <div className="slot-item" key={lvl}>
                                <label>Lvl {lvl}</label>
                                <div className="slot-inputs">
                                    <input 
                                        type="number" 
                                        placeholder="0" 
                                        value={character.spellSlots[lvl]?.max || ''} 
                                        onChange={(e) => handleSlotChange(lvl, 'max', e.target.value)} 
                                    />
                                    <span>/</span>
                                    <input 
                                        type="number" 
                                        placeholder="0" 
                                        className="used-input" 
                                        value={character.spellSlots[lvl]?.used || ''} 
                                        onChange={(e) => handleSlotChange(lvl, 'used', e.target.value)} 
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* --- SPELLS SECTION (PREMIUM TASARIM) --- */}
            <div className="spells-section">
                <div className="section-header">
                    <h2>Spellbook</h2>
                    <button type="button" className="add-spell-btn" onClick={handleAddSpell}>+ LEARN SPELL</button>
                </div>

                <div className="spells-list">
                    {character.spells?.map((spell) => (
                        <div className="spell-card-premium" key={spell.id}>
                            {/* Altın Sarısı Başlık Alanı */}
                            <div className="spell-card-header">
                                <input 
                                    className="spell-name-gold" 
                                    value={spell.name} 
                                    onChange={(e) => handleSpellChange(spell.id, 'name', e.target.value)} 
                                    placeholder="SPELL NAME (e.g. Animate Dead)" 
                                />
                                <button type="button" className="spell-del-btn" onClick={() => handleRemoveSpell(spell.id)}>✕</button>
                            </div>

                            <div className="spell-card-body">
                                {/* Seviye ve Büyü Okulu */}
                                <div className="spell-meta">
                                    <input 
                                        placeholder="3. seviye necromancy" 
                                        value={spell.levelSchool} 
                                        onChange={(e) => handleSpellChange(spell.id, 'levelSchool', e.target.value)} 
                                    />
                                </div>

                                {/* Büyü Özellikleri (Alt alta liste tasarımı) */}
                                <ul className="spell-stats-list">
                                    <li>
                                        <strong>Kullanma Süresi:</strong> 
                                        <input value={spell.castingTime} onChange={(e) => handleSpellChange(spell.id, 'castingTime', e.target.value)} placeholder="1 aksiyon" />
                                    </li>
                                    <li>
                                        <strong>Menzil:</strong> 
                                        <input value={spell.range} onChange={(e) => handleSpellChange(spell.id, 'range', e.target.value)} placeholder="60 fit" />
                                    </li>
                                    <li>
                                        <strong>Bileşenler:</strong> 
                                        <input value={spell.components} onChange={(e) => handleSpellChange(spell.id, 'components', e.target.value)} placeholder="S, B, M (bir tutam kül)" />
                                    </li>
                                    <li>
                                        <strong>Süre:</strong> 
                                        <input value={spell.duration} onChange={(e) => handleSpellChange(spell.id, 'duration', e.target.value)} placeholder="Anlık" />
                                    </li>
                                </ul>

                                {/* Büyü Açıklaması */}
                                <div className="spell-desc-box">
                                    <textarea 
                                        value={spell.description} 
                                        onChange={(e) => handleSpellChange(spell.id, 'description', e.target.value)} 
                                        placeholder="Büyünün etkilerini buraya yazın..." 
                                    />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default DetailsStep;
